INSERT INTO activities (id, ova_id, type, title, description, config, created_at) VALUES
  ('c0a7e17d-0000-4000-8250-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a05', 'quiz', 'Comprueba los conceptos', 'Tres preguntas sobre el ciclo de vida y el acta de constitución.', '{"position":3,"hints_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000001","questions":[{"id":"q1","prompt":"¿Qué documento **autoriza formalmente** el proyecto RutaCaribe?","options":[{"id":"a","text":"El plan para la dirección del proyecto"},{"id":"b","text":"El acta de constitución"},{"id":"c","text":"El registro de interesados"},{"id":"d","text":"El contrato con el proveedor de pagos"}],"answer":"b","explanation":"El acta, firmada por el patrocinador, autoriza el proyecto y da autoridad al director."},{"id":"q2","prompt":"¿Cuál es un objetivo **bien escrito** para el acta?","options":[{"id":"a","text":"Modernizar la venta de tiquetes"},{"id":"b","text":"Hacer la mejor app de transporte del Caribe"},{"id":"c","text":"Vender el 30 % de los tiquetes en línea seis meses después del lanzamiento"},{"id":"d","text":"Usar tecnología de punta"}],"answer":"c","explanation":"Un objetivo útil es medible y tiene plazo: se puede comprobar si se cumplió."},{"id":"q3","prompt":"¿Qué grupo de procesos ocurre **durante todo** el proyecto?","options":[{"id":"a","text":"Inicio"},{"id":"b","text":"Ejecución"},{"id":"c","text":"Monitoreo y control"},{"id":"d","text":"Cierre"}],"answer":"c","explanation":"El monitoreo y control acompaña a las demás fases: compara lo real con lo planeado en todo momento."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8250-000000000002', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a05', 'simulacion', 'Mapa de interesados de RutaCaribe', 'Ubica a cada interesado en la matriz de poder e interés.', '{"position":5,"kind":"clasificacion","review_ai_activity_id":"c0a7e17d-0000-4000-8450-000000000003","instructions":"Lee cada interesado y decide su cuadrante según su poder sobre el proyecto y su interés en él.","params":{"categories":[{"id":"cerca","name":"Gestionar de cerca","hint":"Mucho poder · mucho interés"},{"id":"satisfecho","name":"Mantener satisfecho","hint":"Mucho poder · poco interés"},{"id":"informado","name":"Mantener informado","hint":"Poco poder · mucho interés"},{"id":"monitorear","name":"Monitorear","hint":"Poco poder · poco interés"}],"items":[{"id":"i1","text":"Gerente general de la cooperativa, patrocinadora que firmó el acta","category":"cerca","reason":"Aprueba el presupuesto y sigue el proyecto cada semana."},{"id":"i2","text":"Junta directiva, que solo revisa el proyecto en su informe trimestral","category":"satisfecho","reason":"Puede cancelar el proyecto, pero no sigue el día a día."},{"id":"i3","text":"Taquilleros, que temen que la venta en línea reduzca su trabajo","category":"informado","reason":"Les afecta mucho, pero no deciden sobre el proyecto: hay que informarlos y acompañarlos."},{"id":"i4","text":"Pasajeros frecuentes que piden comprar desde el celular","category":"informado","reason":"Son los usuarios finales y les interesa mucho, aunque no tienen autoridad sobre el proyecto."},{"id":"i5","text":"Superintendencia de Transporte, que regula la venta de tiquetes","category":"satisfecho","reason":"Su norma es obligatoria, pero no participa en el proyecto: basta con cumplirla y consultarla."},{"id":"i6","text":"Proveedor de la pasarela PSE, del que depende el pago en línea","category":"cerca","reason":"Su integración está en la ruta crítica y tiene mucho interés comercial."},{"id":"i7","text":"Empresa de aseo que limpia las oficinas de la cooperativa","category":"monitorear","reason":"Ni el proyecto la afecta ni ella lo afecta."},{"id":"i8","text":"Conductores de los buses","category":"monitorear","reason":"El sistema casi no cambia su trabajo; basta con observar si eso cambia."}]}}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8250-000000000003', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a05', 'caso_estudio', 'El acta que nadie firmó', 'El equipo ya empezó a programar sin acta. Ayuda a ordenar el inicio del proyecto.', '{"position":7,"review_ai_activity_id":"c0a7e17d-0000-4000-8450-000000000001","variant_ai_activity_id":"c0a7e17d-0000-4000-8450-000000000002","scenario":"La gerente general de Brisas del Caribe le dijo al jefe de sistemas en un pasillo: *\"Hagan una app para vender tiquetes, que la competencia ya tiene una\"*. Dos desarrolladores empezaron a programar al día siguiente.\n\nTres semanas después:\n- La contadora pregunta quién autorizó comprar un servidor en la nube.\n- El jefe de taquilla se enteró por un pasajero y está molesto.\n- Nadie sabe si la app debe vender también las rutas intermunicipales a Sincelejo.\n- La gerente pregunta cuándo estará lista y cuánto va a costar.\n\nTe nombran director del proyecto para \"poner orden\".","questions":[{"id":"p1","prompt":"¿Qué problemas del caso se explican por la falta de un acta de constitución?","placeholder":"Sin acta…"},{"id":"p2","prompt":"Redacta los elementos clave del acta de RutaCaribe: propósito, dos objetivos medibles y dos requisitos de alto nivel.","placeholder":"Propósito… Objetivos… Requisitos…"},{"id":"p3","prompt":"¿Qué harías con el jefe de taquilla y con los desarrolladores esta semana?","placeholder":"Con el jefe de taquilla… Con los desarrolladores…"}],"rubric":[{"id":"c1","name":"Diagnóstico","description":"Relaciona los problemas (autoridad para gastar, alcance difuso, plazos) con la ausencia del acta."},{"id":"c2","name":"Objetivos medibles","description":"Propone objetivos con métrica y plazo, y requisitos de alto nivel coherentes con el caso."},{"id":"c3","name":"Interesados","description":"Reconoce al jefe de taquilla como interesado clave y propone cómo involucrarlo."},{"id":"c4","name":"Orden del inicio","description":"Propone formalizar antes de seguir: firma del acta, alcance inicial y plan, sin descartar el trabajo útil ya hecho."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8250-000000000004', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a05', 'colaborativa', 'Reunión de arranque (kickoff)', 'El equipo discute cómo planificar RutaCaribe. Aporta desde tu rol.', '{"position":8,"role":"Director del proyecto","synthesis_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000004","prompt":"Con el acta firmada, el equipo se reúne para decidir cuánto planificar antes de empezar a construir RutaCaribe y cómo mantener informados a los interesados.","contributions":[{"author":"Valentina Orozco","role":"Product owner","text":"Propongo trabajar con sprints de dos semanas y planificar en detalle solo el primero. Lo demás lo iremos descubriendo con los usuarios."},{"author":"Andrés Castillo","role":"Analista de calidad","text":"La gerente necesita una fecha y un presupuesto para diciembre. Sin un plan con líneas base no vamos a poder decir si vamos atrasados."},{"author":"Daniela Acosta","role":"Administradora de infraestructura","text":"Me preocupa que nadie haya hablado con la Superintendencia. Si la norma exige factura electrónica en cada tiquete, eso cambia todo el plan."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8250-000000000005', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a05', 'quiz', 'Autoevaluación: inicio y planificación', 'Cinco preguntas calificadas. Tu resultado queda en tu historial.', '{"position":100,"evaluation_id":"c0a7e17d-0000-4000-8350-000000000001","explain_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000002","questions":[{"id":"e1","prompt":"¿Quién firma el acta de constitución?","options":[{"id":"a","text":"El director del proyecto"},{"id":"b","text":"El equipo de desarrollo"},{"id":"c","text":"El patrocinador"},{"id":"d","text":"Los usuarios finales"}]},{"id":"e2","prompt":"Un interesado con mucho poder y poco interés en el proyecto se debe…","options":[{"id":"a","text":"Gestionar de cerca"},{"id":"b","text":"Mantener satisfecho"},{"id":"c","text":"Mantener informado"},{"id":"d","text":"Ignorar"}]},{"id":"e3","prompt":"¿Qué integra el plan para la dirección del proyecto?","options":[{"id":"a","text":"Solo el cronograma"},{"id":"b","text":"Las líneas base y los planes subsidiarios de cada área"},{"id":"c","text":"El código fuente y los manuales"},{"id":"d","text":"El acta y el contrato"}]},{"id":"e4","prompt":"Detallar primero lo cercano y dejar general lo lejano se llama…","options":[{"id":"a","text":"Elaboración progresiva"},{"id":"b","text":"Enchapado en oro"},{"id":"c","text":"Ejecución rápida"},{"id":"d","text":"Corrupción del alcance"}]},{"id":"e5","prompt":"¿Cuál de estos es un interesado del proyecto RutaCaribe?","options":[{"id":"a","text":"Solo quien paga el proyecto"},{"id":"b","text":"Solo el equipo de desarrollo"},{"id":"c","text":"Cualquiera que afecte el proyecto o se vea afectado por él"},{"id":"d","text":"Solo los usuarios que compran tiquetes"}]}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8210-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a01', 'quiz', 'Comprueba los conceptos', 'Tres preguntas rápidas sobre alcance del producto, del proyecto y el enunciado del alcance.', '{"position":3,"hints_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000001","questions":[{"id":"q1","prompt":"¿Cuál de estos elementos pertenece al alcance del **producto** RutaCaribe?","options":[{"id":"a","text":"Capacitar a los taquilleros en el nuevo sistema"},{"id":"b","text":"Seleccionar la silla en un mapa del bus"},{"id":"c","text":"Realizar reuniones semanales de seguimiento"},{"id":"d","text":"Elaborar el plan de pruebas"}],"answer":"b","explanation":"Seleccionar la silla es una función del producto. Capacitar, hacer reuniones y planear pruebas es trabajo del proyecto."},{"id":"q2","prompt":"¿Por qué conviene escribir las **exclusiones** en el enunciado del alcance?","options":[{"id":"a","text":"Porque el PMBOK exige que el documento tenga al menos tres secciones"},{"id":"b","text":"Para reducir el presupuesto del proyecto"},{"id":"c","text":"Para evitar malentendidos sobre lo que no se entregará"},{"id":"d","text":"Para que el equipo pueda agregar funciones extra sin aprobación"}],"answer":"c","explanation":"Las exclusiones fijan expectativas: lo que no está escrito como incluido suele darse por incluido."},{"id":"q3","prompt":"¿Qué proceso responde a la pregunta *\"¿el cliente acepta lo entregado?\"*","options":[{"id":"a","text":"Controlar el alcance"},{"id":"b","text":"Validar el alcance"},{"id":"c","text":"Definir el alcance"},{"id":"d","text":"Recopilar requisitos"}],"answer":"b","explanation":"Validar el alcance formaliza la aceptación de los entregables por parte del cliente."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8210-000000000002', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a01', 'simulacion', 'Arma la EDT de RutaCaribe', 'Ubica cada elemento en la rama correcta de la EDT y aplica la regla del 100 %.', '{"position":6,"kind":"edt","review_ai_activity_id":"c0a7e17d-0000-4000-8410-000000000003","instructions":"Arrastra cada elemento a la rama de la EDT a la que pertenece. Algunos elementos no deberían estar en la EDT: déjalos en la bandeja de descartes.","params":{"branches":[{"id":"gestion","name":"1. Gestión del proyecto"},{"id":"web","name":"2. Plataforma web de venta"},{"id":"movil","name":"3. Aplicación móvil"},{"id":"pagos","name":"4. Integración de pagos"},{"id":"despliegue","name":"5. Puesta en producción"}],"items":[{"id":"i1","text":"Acta de constitución","branch":"gestion"},{"id":"i2","text":"Informes de avance","branch":"gestion"},{"id":"i3","text":"Mapa de sillas del bus","branch":"web"},{"id":"i4","text":"Buscador de rutas y horarios","branch":"web"},{"id":"i5","text":"Tiquete digital con código QR","branch":"movil"},{"id":"i6","text":"Notificaciones de viaje","branch":"movil"},{"id":"i7","text":"Pasarela PSE","branch":"pagos"},{"id":"i8","text":"Conciliación de pagos con tesorería","branch":"pagos"},{"id":"i9","text":"Capacitación a taquilleros","branch":"despliegue"},{"id":"i10","text":"Migración de la base de clientes","branch":"despliegue"},{"id":"i11","text":"Venta de encomiendas","branch":null,"reason":"Está en las exclusiones del alcance."},{"id":"i12","text":"Programar el login","branch":null,"reason":"Es una actividad (verbo), no un entregable."}]}}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8210-000000000003', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a01', 'caso_estudio', 'La petición del gerente', 'Analiza una solicitud de cambio en plena construcción y recibe retroalimentación de la IA con una rúbrica.', '{"position":8,"review_ai_activity_id":"c0a7e17d-0000-4000-8410-000000000001","variant_ai_activity_id":"c0a7e17d-0000-4000-8410-000000000002","scenario":"RutaCaribe va en la **semana 7 de 16**. La línea base del alcance está aprobada y el equipo avanza según lo planeado.\n\nEn el comité semanal, el gerente de la cooperativa dice:\n\n> *\"Vi que la competencia ya vende encomiendas por su app. Necesito que RutaCaribe también lo haga. No debe ser difícil: es casi lo mismo que un tiquete, ¿no? Lo quiero en la misma fecha de lanzamiento.\"*\n\nEl líder técnico estima que el módulo de encomiendas requiere unas **5 semanas** de trabajo de dos desarrolladores. El enunciado del alcance lista la venta de encomiendas como **exclusión** explícita.","questions":[{"id":"p1","prompt":"¿Esta petición es un cambio de alcance? Justifica tu respuesta con lo que dice la línea base.","placeholder":"Sí / No, porque…"},{"id":"p2","prompt":"Describe, paso a paso, cómo gestionarías la petición como director del proyecto.","placeholder":"Primero… luego…"},{"id":"p3","prompt":"¿Qué impacto tendría aceptarla sin ajustar nada más? Usa la triple restricción.","placeholder":"Si se mantiene la fecha y el presupuesto…"}],"rubric":[{"id":"c1","name":"Identificación del cambio","description":"Reconoce que es un cambio porque contradice una exclusión de la línea base."},{"id":"c2","name":"Proceso de control de cambios","description":"Propone solicitud formal, análisis de impacto, decisión del CCB y actualización de líneas base."},{"id":"c3","name":"Análisis de impacto","description":"Relaciona alcance, tiempo, costo y calidad con datos del caso (5 semanas, 2 desarrolladores)."},{"id":"c4","name":"Comunicación con el interesado","description":"Responde al gerente con alternativas (fase 2, más recursos, mover la fecha) sin rechazar de plano."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8210-000000000004', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a01', 'colaborativa', 'Sesión del Comité de Control de Cambios', 'Lee las posturas de tu equipo, aporta la tuya y obtén una síntesis de la decisión.', '{"position":9,"role":"Líder técnico","synthesis_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000004","prompt":"El CCB debe decidir sobre la solicitud de agregar venta de encomiendas a RutaCaribe antes del lanzamiento. Cada integrante del comité presenta su postura.","contributions":[{"author":"Valentina Orozco","role":"Product owner","text":"Las encomiendas son el 18 % de los ingresos de la cooperativa. Si la competencia ya las vende, no tenerlas puede costarnos clientes. Propongo incluirlas, aunque sea con funciones mínimas."},{"author":"Andrés Castillo","role":"Analista de calidad","text":"Si metemos el módulo sin mover la fecha, las pruebas de pagos se recortan. Ese es justo el módulo con más riesgo. No firmo un lanzamiento sin pruebas completas de PSE."},{"author":"Mónica Ríos","role":"Patrocinadora (gerencia financiera)","text":"El presupuesto aprobado no tiene margen para contratar más desarrolladores este semestre. Cualquier opción que implique más personal necesita otra aprobación de la junta."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8210-000000000005', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a01', 'quiz', 'Autoevaluación: gestión del alcance', 'Cinco preguntas calificadas. Tu resultado queda en tu historial.', '{"position":100,"evaluation_id":"c0a7e17d-0000-4000-8310-000000000001","explain_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000002","questions":[{"id":"e1","prompt":"¿Qué conforma la **línea base del alcance**?","options":[{"id":"a","text":"El acta de constitución y el registro de interesados"},{"id":"b","text":"El enunciado del alcance, la EDT y su diccionario aprobados"},{"id":"c","text":"El cronograma y el presupuesto aprobados"},{"id":"d","text":"La matriz de trazabilidad de requisitos"}]},{"id":"e2","prompt":"Según la **regla del 100 %**, la EDT…","options":[{"id":"a","text":"Debe completarse al 100 % antes de iniciar el proyecto"},{"id":"b","text":"Incluye todo el trabajo del proyecto y nada más"},{"id":"c","text":"Asigna el 100 % del presupuesto al primer nivel"},{"id":"d","text":"Exige que cada paquete dure al menos 100 horas"}]},{"id":"e3","prompt":"¿Cuál es el mejor nombre para un elemento de la EDT?","options":[{"id":"a","text":"Programar el módulo de pagos"},{"id":"b","text":"Revisar con el cliente"},{"id":"c","text":"Módulo de pagos"},{"id":"d","text":"Semana 3"}]},{"id":"e4","prompt":"El equipo agrega por iniciativa propia un modo oscuro que nadie solicitó. Esto es un ejemplo de…","options":[{"id":"a","text":"Enchapado en oro (gold plating)"},{"id":"b","text":"Validación del alcance"},{"id":"c","text":"Corrupción del alcance por presión del cliente"},{"id":"d","text":"Gestión adecuada de requisitos"}]},{"id":"e5","prompt":"¿Quién aprueba o rechaza formalmente una solicitud de cambio?","options":[{"id":"a","text":"El desarrollador que la implementará"},{"id":"b","text":"El cliente que la solicita"},{"id":"c","text":"El Comité de Control de Cambios"},{"id":"d","text":"El analista de calidad"}]}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8220-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a02', 'quiz', 'Comprueba los conceptos', 'Tres preguntas sobre dependencias, estimación y procesos del cronograma.', '{"position":3,"hints_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000001","questions":[{"id":"q1","prompt":"Las pruebas integrales de RutaCaribe no pueden empezar hasta que termine el desarrollo de la app. ¿Qué tipo de dependencia es?","options":[{"id":"a","text":"Inicio a inicio"},{"id":"b","text":"Fin a inicio"},{"id":"c","text":"Fin a fin"},{"id":"d","text":"Inicio a fin"}],"answer":"b","explanation":"La sucesora (pruebas) empieza cuando la predecesora (desarrollo) termina: fin a inicio."},{"id":"q2","prompt":"Para el módulo de pagos el equipo estima 2 semanas en el mejor caso, 4 lo más probable y 12 en el peor. ¿Cuál es la estimación PERT?","options":[{"id":"a","text":"4 semanas"},{"id":"b","text":"5 semanas"},{"id":"c","text":"6 semanas"},{"id":"d","text":"7 semanas"}],"answer":"b","explanation":"(2 + 4 × 4 + 12) / 6 = 30 / 6 = 5 semanas."},{"id":"q3","prompt":"¿En qué proceso se obtiene la **línea base del cronograma**?","options":[{"id":"a","text":"Definir las actividades"},{"id":"b","text":"Secuenciar las actividades"},{"id":"c","text":"Desarrollar el cronograma"},{"id":"d","text":"Controlar el cronograma"}],"answer":"c","explanation":"Desarrollar el cronograma integra secuencia, duraciones y recursos, y produce la línea base."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8220-000000000002', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a02', 'simulacion', 'Encuentra la ruta crítica de RutaCaribe', 'Calcula la duración, la ruta crítica y las holguras, y prueba qué pasa cuando algo se retrasa.', '{"position":6,"kind":"cpm","review_ai_activity_id":"c0a7e17d-0000-4000-8420-000000000003","instructions":"Con la tabla de actividades, calcula la duración del proyecto, marca las actividades de la ruta crítica y responde las preguntas. Al comprobar verás el Gantt y podrás simular retrasos.","params":{"unit":"semanas","activities":[{"id":"A","name":"Requisitos y diseño UX","duration":4,"predecessors":[]},{"id":"B","name":"Arquitectura y base de datos","duration":2,"predecessors":["A"]},{"id":"C","name":"Plataforma web de venta","duration":5,"predecessors":["B"]},{"id":"D","name":"Aplicación móvil","duration":6,"predecessors":["B"]},{"id":"E","name":"Integración de pagos PSE","duration":4,"predecessors":["B"]},{"id":"F","name":"Pruebas integrales","duration":2,"predecessors":["C","D","E"]},{"id":"G","name":"Capacitación a taquilleros","duration":2,"predecessors":["C"]},{"id":"H","name":"Puesta en producción","duration":2,"predecessors":["F","G"]}],"slack_question":"E","delay":{"activity":"E","amount":3}}}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8220-000000000003', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a02', 'caso_estudio', '"Lo necesito para el 1 de diciembre"', 'La gerencia pide adelantar el lanzamiento dos semanas. Decide cómo comprimir el cronograma.', '{"position":8,"review_ai_activity_id":"c0a7e17d-0000-4000-8420-000000000001","variant_ai_activity_id":"c0a7e17d-0000-4000-8420-000000000002","scenario":"El cronograma aprobado de RutaCaribe dura **16 semanas** y su ruta crítica es *Requisitos → Arquitectura → Aplicación móvil → Pruebas integrales → Puesta en producción*. La plataforma web tiene 1 semana de holgura y la integración de pagos, 2.\n\nLa gerente de la cooperativa escribe:\n\n> *\"Nos confirmaron que la temporada alta empieza el 1 de diciembre. Necesito RutaCaribe en producción **dos semanas antes** de lo planeado. Díganme qué necesitan.\"*\n\nEl equipo tiene estas opciones:\n- Contratar un segundo desarrollador móvil por **$18 millones**; el líder técnico calcula que acortaría la app de 6 a 4 semanas.\n- Empezar las pruebas integrales mientras se termina la app (ejecución rápida), con riesgo de retrabajo.\n- Contratar un desarrollador web extra por **$12 millones** para acortar la plataforma web de 5 a 3 semanas.","questions":[{"id":"p1","prompt":"¿Qué opciones adelantan de verdad la fecha de lanzamiento y cuáles no? Explica por qué usando la ruta crítica.","placeholder":"La opción que realmente adelanta la fecha es… porque…"},{"id":"p2","prompt":"Si se acorta la app en 2 semanas, ¿la ruta crítica sigue siendo la misma? ¿Qué debe vigilar el equipo?","placeholder":"Después de acortar la app…"},{"id":"p3","prompt":"Redacta tu recomendación a la gerente, con costos y riesgos de la opción que elijas.","placeholder":"Recomendamos…"}],"rubric":[{"id":"c1","name":"Uso de la ruta crítica","description":"Reconoce que solo acortar actividades críticas adelanta el final y que acortar la web (con holgura) no sirve."},{"id":"c2","name":"Cambio de la ruta crítica","description":"Detecta que al acortar la app aparecen nuevas rutas críticas o casi críticas (web y pagos) y que las holguras se reducen."},{"id":"c3","name":"Costo y riesgo de la compresión","description":"Compara intensificación (costo de $18 millones, ley de Brooks) con ejecución rápida (riesgo de retrabajo)."},{"id":"c4","name":"Recomendación al interesado","description":"Presenta una recomendación clara, con cifras del caso y lo que la gerencia debe aprobar."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8220-000000000004', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a02', 'colaborativa', 'Reunión de seguimiento: la app va atrasada', 'La app móvil lleva una semana de retraso. Escucha al equipo y propone qué hacer.', '{"position":9,"role":"Directora o director del proyecto","synthesis_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000004","prompt":"Semana 9 de 16. La aplicación móvil, que está en la ruta crítica, acumula una semana de retraso por problemas con el mapa de sillas. El equipo se reúne para decidir cómo recuperar el tiempo.","contributions":[{"author":"Santiago Pineda","role":"Desarrollador móvil","text":"El mapa de sillas tiene que funcionar con buses de 2 pisos y no estaba en el diseño original. Puedo recuperar la semana si me quitan las notificaciones de viaje de esta entrega y las hacemos en la siguiente versión."},{"author":"Camila Herrera","role":"Desarrolladora web","text":"Yo tengo una semana de holgura. Puedo ayudar con el mapa de sillas porque ya lo hice en la web con la misma librería. Eso sí, alguien tiene que cubrir mis pruebas."},{"author":"Andrés Castillo","role":"Analista de calidad","text":"Podríamos empezar las pruebas de la app por módulos desde ya, en lugar de esperar a que esté completa. Encontraríamos errores antes, aunque algunas pruebas habría que repetirlas."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8220-000000000005', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a02', 'quiz', 'Autoevaluación: gestión del cronograma', 'Cinco preguntas calificadas. Tu resultado queda en tu historial.', '{"position":100,"evaluation_id":"c0a7e17d-0000-4000-8320-000000000001","explain_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000002","questions":[{"id":"e1","prompt":"¿Qué es la **ruta crítica**?","options":[{"id":"a","text":"La secuencia de actividades más costosas del proyecto"},{"id":"b","text":"La secuencia más larga de actividades dependientes, que define la duración mínima"},{"id":"c","text":"Las actividades con más riesgo técnico"},{"id":"d","text":"Las actividades que dirige el patrocinador"}]},{"id":"e2","prompt":"Una actividad tiene inicio temprano en la semana 6 e inicio tardío en la semana 9. ¿Cuál es su holgura total?","options":[{"id":"a","text":"0 semanas"},{"id":"b","text":"3 semanas"},{"id":"c","text":"6 semanas"},{"id":"d","text":"15 semanas"}]},{"id":"e3","prompt":"Una actividad con 2 semanas de holgura se retrasa 3 semanas. ¿Qué pasa con la fecha final del proyecto?","options":[{"id":"a","text":"No cambia, porque tenía holgura"},{"id":"b","text":"Se retrasa 3 semanas"},{"id":"c","text":"Se retrasa 1 semana"},{"id":"d","text":"Se adelanta 2 semanas"}]},{"id":"e4","prompt":"Agregar un desarrollador a una actividad crítica para terminarla antes es…","options":[{"id":"a","text":"Ejecución rápida (fast tracking)"},{"id":"b","text":"Nivelación de recursos"},{"id":"c","text":"Intensificación (crashing)"},{"id":"d","text":"Estimación análoga"}]},{"id":"e5","prompt":"¿Qué riesgo introduce principalmente la **ejecución rápida**?","options":[{"id":"a","text":"Retrabajo, por hacer en paralelo lo que dependía de otra actividad"},{"id":"b","text":"Un aumento directo del costo de mano de obra"},{"id":"c","text":"La pérdida de la línea base del alcance"},{"id":"d","text":"Ninguno: es una técnica sin efectos secundarios"}]}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8230-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a03', 'quiz', 'Comprueba los conceptos', 'Tres preguntas sobre presupuesto, reservas y los datos del valor ganado.', '{"position":3,"hints_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000001","questions":[{"id":"q1","prompt":"¿Qué reserva **no** forma parte de la línea base de costos?","options":[{"id":"a","text":"La reserva para contingencias"},{"id":"b","text":"La reserva de gestión"},{"id":"c","text":"El costo de los paquetes de trabajo"},{"id":"d","text":"El costo de las licencias de software"}],"answer":"b","explanation":"La reserva de gestión cubre imprevistos no identificados y queda fuera de la línea base; usarla requiere aprobación."},{"id":"q2","prompt":"El módulo de pagos tiene un presupuesto de $40 millones, está al 50 % y se han gastado $30 millones. ¿Cuál es su **EV**?","options":[{"id":"a","text":"$15 millones"},{"id":"b","text":"$20 millones"},{"id":"c","text":"$30 millones"},{"id":"d","text":"$40 millones"}],"answer":"b","explanation":"EV = % completado × presupuesto = 50 % × $40 millones = $20 millones. Lo gastado es el AC."},{"id":"q3","prompt":"¿Por qué la línea base de costos tiene forma de **curva S**?","options":[{"id":"a","text":"Porque los costos siempre se duplican a mitad del proyecto"},{"id":"b","text":"Porque el gasto acumulado empieza lento, se acelera y luego se aplana"},{"id":"c","text":"Porque así lo exige el formato del PMBOK"},{"id":"d","text":"Porque las reservas se gastan al final"}],"answer":"b","explanation":"Pocas personas al inicio, todo el equipo en el centro y cierre al final: el acumulado dibuja una S."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8230-000000000002', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a03', 'simulacion', 'Informe de valor ganado de RutaCaribe', 'Calcula los indicadores en la semana 8, diagnostica el proyecto y explora qué pasaría con otros resultados.', '{"position":5,"kind":"evm","review_ai_activity_id":"c0a7e17d-0000-4000-8430-000000000003","instructions":"Usa el informe de corte para calcular los indicadores. Escribe los valores en millones de pesos y los índices con dos decimales.","params":{"currency":"millones","bac":480,"week":8,"total_weeks":16,"pv":[0,10,24,42,64,90,128,180,240,300,350,392,424,448,464,474,480],"ev":[0,9,21,36,54,75,104,146,192],"ac":[0,11,25,43,64,88,124,172,228]}}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8230-000000000003', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a03', 'caso_estudio', 'El comité financiero de la semana 8', 'Presenta el estado de costos a la junta y propone cómo cerrar la brecha.', '{"position":6,"review_ai_activity_id":"c0a7e17d-0000-4000-8430-000000000001","variant_ai_activity_id":"c0a7e17d-0000-4000-8430-000000000002","scenario":"Semana 8 de 16. El informe de valor ganado de RutaCaribe muestra **CPI = 0,84** y **SPI = 0,80**. Con ese desempeño, el costo final estimado es de **$570 millones**, $90 millones por encima del presupuesto de $480 millones.\n\nAl revisar las causas, el equipo encontró que:\n- La integración con PSE tomó el doble de horas porque la documentación del proveedor estaba desactualizada.\n- Se contrató un diseñador externo por horas para el mapa de sillas, que no estaba presupuestado.\n- La reserva para contingencias, de $30 millones, ya se usó en un 60 %.\n\nLa gerente financiera dice en el comité:\n\n> *\"No hay más dinero este año. Quiero saber cómo vamos a terminar el proyecto con lo aprobado o qué tenemos que sacrificar.\"*","questions":[{"id":"p1","prompt":"Explica a la junta, sin tecnicismos, qué significan un CPI de 0,84 y un SPI de 0,80 para RutaCaribe.","placeholder":"Por cada peso que gastamos…"},{"id":"p2","prompt":"¿Qué opciones tiene el proyecto para terminar sin superar los $480 millones? Evalúa al menos dos.","placeholder":"Opción 1… Opción 2…"},{"id":"p3","prompt":"¿Qué harías para que el CPI de la segunda mitad del proyecto no siga en 0,84?","placeholder":"Para las próximas semanas…"}],"rubric":[{"id":"c1","name":"Interpretación de los índices","description":"Traduce CPI y SPI a lenguaje del negocio (rinde 84 centavos por peso, avanza al 80 % del ritmo)."},{"id":"c2","name":"Opciones de recuperación","description":"Propone alternativas viables (reducir alcance, diferir funciones, renegociar) y sus consecuencias."},{"id":"c3","name":"Acciones sobre las causas","description":"Ataca las causas encontradas (estimación de integraciones, costos no presupuestados, uso de reservas)."},{"id":"c4","name":"Uso de los datos del caso","description":"Usa las cifras del caso (EAC, VAC, reserva) con coherencia en sus argumentos."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8230-000000000004', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a03', 'colaborativa', 'Qué recortar para cuidar el presupuesto', 'El equipo debe proponer recortes al alcance. Aporta tu criterio y obtén una síntesis.', '{"position":8,"role":"Analista financiero del proyecto","synthesis_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000004","prompt":"La junta pidió terminar RutaCaribe con los $480 millones aprobados. El equipo debe proponer qué funciones pasan a una segunda versión para cerrar una brecha estimada de $90 millones.","contributions":[{"author":"Valentina Orozco","role":"Product owner","text":"La compra de tiquetes y el pago con PSE no se tocan: son el producto. Podemos pasar a la segunda versión las notificaciones de viaje y el programa de puntos. Eso ahorra unos $45 millones."},{"author":"Juan David Barrios","role":"Líder técnico","text":"El pago con tarjeta de crédito duplica el trabajo de integración y de seguridad. Si salimos solo con PSE ahorramos $35 millones, aunque algunos clientes no podrán pagar."},{"author":"Mónica Ríos","role":"Patrocinadora (gerencia financiera)","text":"Lo que recortemos tiene que estar escrito como exclusión y aprobado por el comité de cambios. No quiero que en enero me digan que eso \"sí estaba incluido\"."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8230-000000000005', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a03', 'quiz', 'Autoevaluación: gestión de costos', 'Cinco preguntas calificadas. Tu resultado queda en tu historial.', '{"position":100,"evaluation_id":"c0a7e17d-0000-4000-8330-000000000001","explain_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000002","questions":[{"id":"e1","prompt":"Un proyecto tiene EV = $100 millones y AC = $125 millones. ¿Cuál es su CPI?","options":[{"id":"a","text":"1,25"},{"id":"b","text":"0,80"},{"id":"c","text":"−25"},{"id":"d","text":"0,25"}]},{"id":"e2","prompt":"Un SPI de 1,10 significa que el proyecto…","options":[{"id":"a","text":"Gasta 10 % más de lo planeado"},{"id":"b","text":"Avanza 10 % más rápido de lo planeado"},{"id":"c","text":"Está 10 % atrasado"},{"id":"d","text":"Terminará con un 10 % de ahorro"}]},{"id":"e3","prompt":"Con BAC = $480 millones y CPI = 0,80, ¿cuál es el EAC si el desempeño se mantiene?","options":[{"id":"a","text":"$384 millones"},{"id":"b","text":"$480 millones"},{"id":"c","text":"$560 millones"},{"id":"d","text":"$600 millones"}]},{"id":"e4","prompt":"¿Qué dato representa el trabajo realmente terminado, valorado con el presupuesto?","options":[{"id":"a","text":"PV, valor planificado"},{"id":"b","text":"EV, valor ganado"},{"id":"c","text":"AC, costo real"},{"id":"d","text":"BAC, presupuesto hasta la conclusión"}]},{"id":"e5","prompt":"El proyecto tiene CV negativa y SV positiva. ¿Cuál es la explicación más probable?","options":[{"id":"a","text":"Va atrasado y por debajo del presupuesto"},{"id":"b","text":"Va adelantado gracias a gastar más de lo planeado, por ejemplo con horas extra"},{"id":"c","text":"Va exactamente según lo planeado"},{"id":"d","text":"El presupuesto estaba sobreestimado"}]}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8240-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a04', 'quiz', 'Comprueba los conceptos', 'Tres preguntas sobre riesgos, problemas y cómo se escriben.', '{"position":3,"hints_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000001","questions":[{"id":"q1","prompt":"¿Cuál de estas situaciones es un **riesgo** y no un problema?","options":[{"id":"a","text":"El servidor de pruebas se cayó esta mañana"},{"id":"b","text":"El desarrollador móvil renunció ayer"},{"id":"c","text":"El proveedor de PSE podría cambiar su API antes del lanzamiento"},{"id":"d","text":"La factura del hosting llegó más alta de lo presupuestado"}],"answer":"c","explanation":"Un riesgo es incierto y futuro. Las demás situaciones ya ocurrieron: son problemas."},{"id":"q2","prompt":"Una agencia de turismo quiere vender tiquetes de RutaCaribe en sus paquetes. Para el proyecto esto es…","options":[{"id":"a","text":"Una amenaza, porque agrega trabajo"},{"id":"b","text":"Una oportunidad"},{"id":"c","text":"Un problema"},{"id":"d","text":"Una restricción"}],"answer":"b","explanation":"Es un evento incierto con efecto positivo sobre los objetivos: una oportunidad."},{"id":"q3","prompt":"¿Qué tiene un enunciado de riesgo bien escrito?","options":[{"id":"a","text":"Solo el nombre del riesgo"},{"id":"b","text":"Causa, riesgo y efecto"},{"id":"c","text":"La fecha en que va a ocurrir"},{"id":"d","text":"El costo exacto del riesgo"}],"answer":"b","explanation":"Causa, riesgo y efecto permiten entender por qué podría ocurrir y qué objetivo afecta."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8240-000000000002', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a04', 'simulacion', 'Prioriza los riesgos de RutaCaribe', 'Ubica cada riesgo en la matriz de probabilidad e impacto y elige su respuesta.', '{"position":5,"kind":"riesgos","review_ai_activity_id":"c0a7e17d-0000-4000-8440-000000000003","instructions":"Para cada riesgo del registro, elige su probabilidad, su impacto y la estrategia de respuesta. La matriz se actualiza a medida que avanzas.","params":{"risks":[{"id":"r1","text":"El proveedor de PSE cambia su API durante el desarrollo y la integración debe rehacerse.","type":"amenaza","probability":2,"impact":3,"responses":["mitigar"],"reason":"Es probable y afecta la ruta crítica. Se mitiga con una capa de integración aislada y pruebas en el ambiente de pruebas del proveedor."},{"id":"r2","text":"El único desarrollador que conoce la app móvil renuncia antes del lanzamiento.","type":"amenaza","probability":2,"impact":3,"responses":["mitigar"],"reason":"Se mitiga reduciendo la dependencia de una persona: documentación, revisiones de código y programación en pareja."},{"id":"r3","text":"Los servidores se caen el día del lanzamiento, en plena temporada alta.","type":"amenaza","probability":1,"impact":3,"responses":["transferir","mitigar"],"reason":"Probabilidad baja e impacto alto: prioridad media. Se transfiere con un hosting con acuerdo de nivel de servicio o se mitiga con pruebas de carga."},{"id":"r4","text":"Los taquilleros se resisten a usar el nuevo sistema y siguen vendiendo por WhatsApp.","type":"amenaza","probability":3,"impact":2,"responses":["mitigar"],"reason":"Es muy probable en un cambio de proceso. Se mitiga con capacitación temprana y taquilleros líderes que acompañen a sus compañeros."},{"id":"r5","text":"La librería del mapa de sillas lleva dos años sin mantenimiento y podría fallar en nuevos navegadores.","type":"amenaza","probability":2,"impact":2,"responses":["evitar"],"reason":"Se puede eliminar la amenaza cambiando de librería ahora, cuando todavía es barato."},{"id":"r6","text":"El nuevo logo de la cooperativa llega una semana tarde y hay que cambiar algunos íconos.","type":"amenaza","probability":2,"impact":1,"responses":["aceptar"],"reason":"Impacto bajo: no vale la pena invertir en una respuesta. Se acepta y se ajusta si ocurre."},{"id":"r7","text":"Una agencia de turismo ofrece vender tiquetes de RutaCaribe en sus paquetes de diciembre.","type":"oportunidad","probability":2,"impact":3,"responses":["compartir","explotar"],"reason":"Oportunidad de alto impacto. Se comparte con una alianza con la agencia o se explota asegurando la integración antes de diciembre."}]}}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8240-000000000003', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a04', 'caso_estudio', 'El riesgo que se volvió problema', 'Un riesgo identificado ocurrió en la semana 11. Analiza qué falló y qué hacer ahora.', '{"position":7,"review_ai_activity_id":"c0a7e17d-0000-4000-8440-000000000001","variant_ai_activity_id":"c0a7e17d-0000-4000-8440-000000000002","scenario":"En la semana 3, el equipo de RutaCaribe registró este riesgo con **probabilidad media e impacto alto**:\n\n> *Debido a que solo Santiago conoce el código de la app móvil, puede que su ausencia detenga el desarrollo, lo que retrasaría el lanzamiento.*\n\nLa respuesta planeada fue **mitigar**: documentar el código y hacer revisiones semanales en pareja. El responsable era el líder técnico. Por la presión del cronograma, las revisiones se cancelaron desde la semana 6 y la documentación quedó a medias.\n\nEn la semana 11, Santiago recibe una oferta en Bogotá y anuncia que se va **en dos semanas**. Quedan 5 semanas para el lanzamiento y la app está en la ruta crítica.","questions":[{"id":"p1","prompt":"¿Qué falló en la gestión de este riesgo? Distingue entre la identificación, la respuesta y el monitoreo.","placeholder":"La identificación fue… La respuesta… El monitoreo…"},{"id":"p2","prompt":"Ahora que es un problema, ¿qué harías en las dos semanas que Santiago sigue en el equipo?","placeholder":"En estas dos semanas…"},{"id":"p3","prompt":"¿Qué riesgos nuevos o secundarios aparecen y cómo los registrarías?","placeholder":"Debido a que… puede que… lo que…"}],"rubric":[{"id":"c1","name":"Diagnóstico del proceso","description":"Reconoce que el riesgo estaba bien identificado y que fallaron la implementación y el monitoreo de la respuesta."},{"id":"c2","name":"Gestión del problema","description":"Propone acciones concretas para las dos semanas (transferencia de conocimiento, priorizar documentación, reemplazo)."},{"id":"c3","name":"Riesgos secundarios","description":"Identifica riesgos nuevos (curva de aprendizaje del reemplazo, retraso del lanzamiento) con formato causa, riesgo y efecto."},{"id":"c4","name":"Impacto en el proyecto","description":"Relaciona el problema con la ruta crítica, el cronograma y el uso de reservas."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8240-000000000004', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a04', 'colaborativa', 'Taller de identificación de riesgos', 'El equipo identifica riesgos para el lanzamiento de diciembre. Aporta uno y obtén la síntesis.', '{"position":8,"role":"Responsable de seguridad de la información","synthesis_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000004","prompt":"Faltan cuatro semanas para lanzar RutaCaribe en plena temporada alta. El equipo hace un taller para identificar los riesgos del lanzamiento y priorizar las respuestas.","contributions":[{"author":"Daniela Acosta","role":"Administradora de infraestructura","text":"En diciembre esperamos 5 veces el tráfico normal. No hemos hecho pruebas de carga. Propongo hacerlas ya y contratar capacidad elástica en la nube, aunque suba el costo mensual."},{"author":"Andrés Castillo","role":"Analista de calidad","text":"Me preocupa más el pago duplicado: si PSE responde lento, el usuario vuelve a pagar. Ya pasó una vez en pruebas. Eso es dinero de clientes y la reputación de la cooperativa."},{"author":"Valentina Orozco","role":"Product owner","text":"Hay una oportunidad: la Alcaldía quiere promover la compra en línea en temporada. Si lanzamos a tiempo, podríamos salir en su campaña sin costo."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8240-000000000005', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a04', 'quiz', 'Autoevaluación: gestión de riesgos', 'Cinco preguntas calificadas. Tu resultado queda en tu historial.', '{"position":100,"evaluation_id":"c0a7e17d-0000-4000-8340-000000000001","explain_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000002","questions":[{"id":"e1","prompt":"En una escala de 1 a 3, un riesgo de probabilidad 2 e impacto 3 tiene prioridad…","options":[{"id":"a","text":"Baja"},{"id":"b","text":"Media"},{"id":"c","text":"Alta"},{"id":"d","text":"No se puede calcular"}]},{"id":"e2","prompt":"Contratar un seguro o un hosting con penalidades por caídas es una respuesta de…","options":[{"id":"a","text":"Evitar"},{"id":"b","text":"Transferir"},{"id":"c","text":"Mitigar"},{"id":"d","text":"Aceptar"}]},{"id":"e3","prompt":"Cambiar de librería para eliminar por completo la posibilidad de que la antigua falle es…","options":[{"id":"a","text":"Evitar"},{"id":"b","text":"Mejorar"},{"id":"c","text":"Escalar"},{"id":"d","text":"Aceptar pasivamente"}]},{"id":"e4","prompt":"¿Qué estrategia corresponde a una **oportunidad**?","options":[{"id":"a","text":"Mitigar"},{"id":"b","text":"Transferir"},{"id":"c","text":"Compartir"},{"id":"d","text":"Evitar"}]},{"id":"e5","prompt":"Un riesgo identificado acaba de ocurrir. A partir de ahora se gestiona como…","options":[{"id":"a","text":"Un riesgo residual"},{"id":"b","text":"Un problema (issue)"},{"id":"c","text":"Una oportunidad"},{"id":"d","text":"Una restricción del proyecto"}]}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8260-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a06', 'quiz', 'Comprueba los conceptos', 'Tres preguntas sobre el equipo y la matriz RACI.', '{"position":3,"hints_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000001","questions":[{"id":"q1","prompt":"En una matriz RACI, ¿cuántas personas deben tener la **A** (aprueba) en un mismo entregable?","options":[{"id":"a","text":"Ninguna"},{"id":"b","text":"Exactamente una"},{"id":"c","text":"Todo el equipo"},{"id":"d","text":"Al menos dos, para tener respaldo"}],"answer":"b","explanation":"Un solo dueño de la aprobación evita que la decisión quede en el aire."},{"id":"q2","prompt":"El equipo discute fuerte sobre qué framework usar para la app. Según Tuckman, está en la etapa de…","options":[{"id":"a","text":"Formación"},{"id":"b","text":"Conflicto"},{"id":"c","text":"Desempeño"},{"id":"d","text":"Disolución"}],"answer":"b","explanation":"En la etapa de conflicto chocan ideas y roles. El director facilita acuerdos."},{"id":"q3","prompt":"Las revisiones de código y las auditorías de proceso son actividades de…","options":[{"id":"a","text":"Gestionar la calidad (prevención)"},{"id":"b","text":"Controlar el alcance"},{"id":"c","text":"Cierre del proyecto"},{"id":"d","text":"Gestión de adquisiciones"}],"answer":"a","explanation":"Revisar el proceso para que los defectos no ocurran es gestionar la calidad."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8260-000000000002', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a06', 'simulacion', '¿En qué etapa está el equipo?', 'Clasifica situaciones reales del equipo de RutaCaribe en las etapas de Tuckman.', '{"position":5,"kind":"clasificacion","review_ai_activity_id":"c0a7e17d-0000-4000-8460-000000000003","instructions":"Lee lo que pasa en el equipo y decide en qué etapa de desarrollo está.","params":{"categories":[{"id":"formacion","name":"Formación","hint":"Cortesía, dudas sobre roles"},{"id":"conflicto","name":"Conflicto","hint":"Choques de ideas y de poder"},{"id":"normalizacion","name":"Normalización","hint":"Acuerdos y reglas propias"},{"id":"desempeno","name":"Desempeño","hint":"Autonomía y resultados"}],"items":[{"id":"i1","text":"En la primera reunión todos son muy amables y nadie cuestiona el plan.","category":"formacion","reason":"Cortesía inicial y poca confianza para discrepar."},{"id":"i2","text":"Los desarrolladores preguntan quién decide la arquitectura y a quién reportan.","category":"formacion","reason":"Los roles aún no están claros."},{"id":"i3","text":"Web y móvil discuten porque cada uno quiere diseñar la API a su manera.","category":"conflicto","reason":"Choque de ideas y de control sobre el trabajo."},{"id":"i4","text":"Un desarrollador ignora las decisiones del líder técnico en las revisiones de código.","category":"conflicto","reason":"Se disputa la autoridad dentro del equipo."},{"id":"i5","text":"El equipo acuerda una guía de estilo y que ningún cambio entra sin revisión de otro.","category":"normalizacion","reason":"El equipo crea sus propias reglas de trabajo."},{"id":"i6","text":"La reunión diaria empieza puntual y dura 15 minutos sin que nadie lo pida.","category":"normalizacion","reason":"Las normas acordadas ya se cumplen solas."},{"id":"i7","text":"Ante una caída de PSE, el equipo se organiza solo y la resuelve en una hora.","category":"desempeno","reason":"Autonomía y alto rendimiento sin intervención del director."},{"id":"i8","text":"Los integrantes se cubren entre sí y proponen mejoras al proceso.","category":"desempeno","reason":"Confianza y mejora continua: el equipo rinde por sí mismo."}]}}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8260-000000000003', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a06', 'caso_estudio', 'El equipo que se quemó en la semana 9', 'El equipo trabaja horas extra y la calidad cae. Decide cómo dirigirlo.', '{"position":7,"review_ai_activity_id":"c0a7e17d-0000-4000-8460-000000000001","variant_ai_activity_id":"c0a7e17d-0000-4000-8460-000000000002","scenario":"Semana 9 de 16. Para no atrasarse, el equipo de RutaCaribe lleva tres semanas trabajando hasta las 10 p. m. y algunos sábados.\n\n- Las pruebas encontraron **42 defectos** esta semana; el promedio era 12.\n- Dos desarrolladores dejaron de hablar en la reunión diaria y se comunican solo por chat.\n- La analista de calidad dice que las revisiones de código \"ya no dan tiempo\" y se saltan.\n- La gerente pregunta por qué el informe semanal dice \"en verde\" si hay tantos errores.\n\n*\"Si bajamos el ritmo, no llegamos a diciembre\"*, dice el líder técnico.","questions":[{"id":"p1","prompt":"¿Qué está pasando con el equipo y con la calidad? Relaciona las horas extra con los defectos.","placeholder":"El equipo…"},{"id":"p2","prompt":"¿Qué harías esta semana como director con el equipo, el proceso de calidad y el informe a la gerente?","placeholder":"Con el equipo… Con la calidad… Con el informe…"},{"id":"p3","prompt":"Responde al líder técnico: ¿bajar el ritmo pone en riesgo diciembre? Argumenta.","placeholder":"Le diría que…"}],"rubric":[{"id":"c1","name":"Diagnóstico del equipo","description":"Reconoce el desgaste, el conflicto y la relación entre horas extra, retrabajo y defectos."},{"id":"c2","name":"Calidad","description":"Propone restablecer la prevención (revisiones, pruebas) y explica por qué prevenir es más barato que corregir."},{"id":"c3","name":"Comunicación honesta","description":"Corrige el informe \"en verde\" y comunica a la gerente el estado real con datos."},{"id":"c4","name":"Decisión equilibrada","description":"Plantea alternativas realistas (ritmo sostenible, priorizar alcance, compresión) con sus costos."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8260-000000000004', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a06', 'colaborativa', 'Plan de comunicaciones del lanzamiento', 'El equipo define cómo informar a cada interesado. Aporta desde tu rol.', '{"position":8,"role":"Responsable de comunicaciones del proyecto","synthesis_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000004","prompt":"Faltan seis semanas para el lanzamiento. El equipo decide qué informar, a quién, cada cuánto y por qué medio, para que nadie se entere tarde.","contributions":[{"author":"Valentina Orozco","role":"Product owner","text":"A los taquilleros hay que mostrarles el sistema ya, en persona, no por correo. Si se enteran el día del lanzamiento, lo van a rechazar."},{"author":"Juan David Barrios","role":"Líder técnico","text":"Propongo un tablero público con el avance de cada historia. Así la gerente lo consulta cuando quiera y no nos interrumpe."},{"author":"Mariana López","role":"Asistente de gerencia","text":"La gerente no va a entrar a un tablero. Necesita un resumen de una página los viernes: qué se hizo, qué sigue y qué decisiones le tocan."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8260-000000000005', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a06', 'quiz', 'Autoevaluación: ejecución', 'Cinco preguntas calificadas. Tu resultado queda en tu historial.', '{"position":100,"evaluation_id":"c0a7e17d-0000-4000-8360-000000000001","explain_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000002","questions":[{"id":"e1","prompt":"¿Cuántos canales de comunicación tiene un equipo de 6 personas?","options":[{"id":"a","text":"6"},{"id":"b","text":"12"},{"id":"c","text":"15"},{"id":"d","text":"36"}]},{"id":"e2","prompt":"El equipo ya acordó sus reglas de trabajo y las cumple. Está en la etapa de…","options":[{"id":"a","text":"Formación"},{"id":"b","text":"Conflicto"},{"id":"c","text":"Normalización"},{"id":"d","text":"Disolución"}]},{"id":"e3","prompt":"Inspeccionar la app terminada para encontrar defectos es…","options":[{"id":"a","text":"Gestionar la calidad"},{"id":"b","text":"Controlar la calidad"},{"id":"c","text":"Planificar la calidad"},{"id":"d","text":"Gestionar el conocimiento"}]},{"id":"e4","prompt":"En la matriz RACI, la \"I\" significa que la persona…","options":[{"id":"a","text":"Hace el trabajo"},{"id":"b","text":"Aprueba el entregable"},{"id":"c","text":"Da su opinión antes de decidir"},{"id":"d","text":"Recibe información del avance"}]},{"id":"e5","prompt":"¿Qué fase del proyecto suele consumir la mayor parte del presupuesto?","options":[{"id":"a","text":"Inicio"},{"id":"b","text":"Planificación"},{"id":"c","text":"Ejecución"},{"id":"d","text":"Cierre"}]}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8270-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a07', 'quiz', 'Comprueba los conceptos', 'Tres preguntas sobre monitoreo y control de cambios.', '{"position":3,"hints_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000001","questions":[{"id":"q1","prompt":"Un desarrollador agrega un botón que pidió un taquillero, sin pasar por el comité. ¿Qué está mal?","options":[{"id":"a","text":"Nada, era un cambio pequeño"},{"id":"b","text":"Se cambió la línea base sin análisis ni aprobación"},{"id":"c","text":"Debió pedirlo el patrocinador"},{"id":"d","text":"Los botones no son parte del alcance"}],"answer":"b","explanation":"Todo cambio a una línea base pasa por el control integrado de cambios, aunque parezca pequeño."},{"id":"q2","prompt":"El SPI de la semana es 0,82 y el umbral rojo es menor que 0,85. ¿Qué corresponde?","options":[{"id":"a","text":"Esperar a la próxima semana"},{"id":"b","text":"Cambiar el umbral"},{"id":"c","text":"Analizar la causa y proponer una acción correctiva"},{"id":"d","text":"Reportarlo en verde para no alarmar"}],"answer":"c","explanation":"Un indicador en rojo exige analizar la causa y proponer acciones, no esconderlo."},{"id":"q3","prompt":"¿Qué responde la gestión de la configuración?","options":[{"id":"a","text":"Quién trabaja horas extra"},{"id":"b","text":"Cuál es la versión vigente y qué cambió"},{"id":"c","text":"Cuánto cuesta cada paquete"},{"id":"d","text":"Qué riesgos son prioritarios"}],"answer":"b","explanation":"La configuración mantiene la trazabilidad de versiones de las líneas base y los productos."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8270-000000000002', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a07', 'simulacion', 'La bandeja de solicitudes', 'Clasifica las solicitudes que llegaron a RutaCaribe esta semana.', '{"position":5,"kind":"clasificacion","review_ai_activity_id":"c0a7e17d-0000-4000-8470-000000000003","instructions":"Lee cada solicitud y decide qué tipo de solicitud de cambio es.","params":{"categories":[{"id":"alcance","name":"Cambio de alcance","hint":"Agrega, quita o modifica lo que se entrega"},{"id":"correctiva","name":"Acción correctiva","hint":"Realinea el desempeño con el plan"},{"id":"preventiva","name":"Acción preventiva","hint":"Evita un desvío futuro"},{"id":"defecto","name":"Reparación de defecto","hint":"Corrige un producto que no cumple"}],"items":[{"id":"i1","text":"La junta pide que la app también venda envío de encomiendas.","category":"alcance","reason":"Agrega una función que el enunciado excluyó: cambia el alcance."},{"id":"i2","text":"Agregar inglés a la app para turistas extranjeros.","category":"alcance","reason":"Es una característica nueva del producto."},{"id":"i3","text":"El SPI cayó a 0,80: se propone sumar un desarrollador a la app móvil.","category":"correctiva","reason":"Busca devolver el desempeño del cronograma al plan."},{"id":"i4","text":"El CPI es 0,86: se propone reemplazar horas extra por priorizar historias.","category":"correctiva","reason":"Corrige un desvío de costo ya medido."},{"id":"i5","text":"Antes de diciembre, hacer pruebas de carga para el pico de temporada.","category":"preventiva","reason":"Evita un problema que aún no ocurre."},{"id":"i6","text":"Capacitar a un segundo desarrollador en la app para no depender de uno solo.","category":"preventiva","reason":"Reduce la probabilidad de un desvío futuro."},{"id":"i7","text":"El tiquete QR sale con la fecha del viaje equivocada.","category":"defecto","reason":"El producto no cumple un requisito ya aprobado."},{"id":"i8","text":"El pago con tarjeta falla cuando el nombre tiene tilde.","category":"defecto","reason":"Es un error del producto frente a su especificación."}]}}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8270-000000000003', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a07', 'caso_estudio', 'Las encomiendas vuelven', 'La junta quiere algo que el enunciado excluyó. Gestiona la solicitud de punta a punta.', '{"position":7,"review_ai_activity_id":"c0a7e17d-0000-4000-8470-000000000001","variant_ai_activity_id":"c0a7e17d-0000-4000-8470-000000000002","scenario":"Semana 12 de 16. El enunciado del alcance de RutaCaribe dice: *\"No incluye venta de envío de encomiendas en esta versión\"*.\n\nEn la junta, un socio propone: *\"Ya que estamos, que la app venda también las encomiendas; la competencia lo tiene\"*. La gerente le pide al equipo \"verlo\".\n\nEl equipo estima:\n- **5 semanas** adicionales de desarrollo, 3 de ellas en la ruta crítica.\n- **$65 millones** más; quedan $20 millones de reserva de contingencias.\n- Un riesgo nuevo: el operador de mensajería no tiene API documentada.\n\nEl lanzamiento comprometido es el **1 de diciembre**, en temporada alta.","questions":[{"id":"p1","prompt":"Describe cómo gestionarías esta solicitud paso a paso, desde que se registra hasta que se comunica la decisión.","placeholder":"Primero…"},{"id":"p2","prompt":"Presenta el análisis de impacto al Comité: alcance, cronograma, costo y riesgos.","placeholder":"Alcance… Cronograma… Costo… Riesgos…"},{"id":"p3","prompt":"¿Qué recomendarías al Comité y qué alternativas le darías a la junta?","placeholder":"Recomiendo…"}],"rubric":[{"id":"c1","name":"Proceso formal","description":"Sigue el control integrado de cambios: registro, análisis, decisión del CCB, actualización y comunicación."},{"id":"c2","name":"Análisis de impacto","description":"Usa las cifras del caso para mostrar el efecto en la fecha, el presupuesto y los riesgos."},{"id":"c3","name":"Alternativas","description":"Propone opciones viables (segunda versión, piloto, cambio de fecha) con sus consecuencias."},{"id":"c4","name":"Línea base y configuración","description":"Explica qué documentos y versiones se actualizan si el cambio se aprueba."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8270-000000000004', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a07', 'colaborativa', 'Sesión del Comité de Control de Cambios', 'El comité debate tres solicitudes con presupuesto limitado. Aporta desde tu rol.', '{"position":8,"role":"Representante de los usuarios en el comité","synthesis_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000004","prompt":"Quedan $20 millones de reserva y cuatro semanas. El comité debe priorizar entre tres solicitudes: pago con Nequi, inglés en la app y pruebas de carga.","contributions":[{"author":"Carlos Herrera","role":"Director financiero","text":"Solo apruebo lo que cabe en la reserva. Las pruebas de carga cuestan $8 millones y evitan perder la temporada; eso va primero."},{"author":"Valentina Orozco","role":"Product owner","text":"Nequi es lo que más piden los usuarios jóvenes. Si no está, muchos seguirán comprando en taquilla y el objetivo del 30 % no se cumple."},{"author":"Sebastián Marrugo","role":"Líder de la app móvil","text":"Inglés parece fácil, pero toca todas las pantallas y las pruebas. Propongo dejarlo para la versión 2."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8270-000000000005', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a07', 'quiz', 'Autoevaluación: control de cambios', 'Cinco preguntas calificadas. Tu resultado queda en tu historial.', '{"position":100,"evaluation_id":"c0a7e17d-0000-4000-8370-000000000001","explain_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000002","questions":[{"id":"e1","prompt":"¿Quién aprueba o rechaza un cambio a la línea base?","options":[{"id":"a","text":"El desarrollador que lo implementa"},{"id":"b","text":"El Comité de Control de Cambios"},{"id":"c","text":"El usuario que lo pidió"},{"id":"d","text":"Nadie: se implementa si hay tiempo"}]},{"id":"e2","prompt":"Capacitar a otra persona para no depender de un solo experto es una…","options":[{"id":"a","text":"Acción correctiva"},{"id":"b","text":"Acción preventiva"},{"id":"c","text":"Reparación de defecto"},{"id":"d","text":"Cambio de alcance"}]},{"id":"e3","prompt":"¿Qué paso va justo antes de la decisión del comité?","options":[{"id":"a","text":"Implementar el cambio"},{"id":"b","text":"Actualizar la línea base"},{"id":"c","text":"Analizar el impacto"},{"id":"d","text":"Verificar el cambio"}]},{"id":"e4","prompt":"Un cambio aprobado a la línea base de alcance produce…","options":[{"id":"a","text":"Una nueva versión registrada de la línea base"},{"id":"b","text":"Un nuevo proyecto"},{"id":"c","text":"La cancelación del acta"},{"id":"d","text":"Ningún registro, solo el cambio en el código"}]},{"id":"e5","prompt":"El tiquete QR no muestra la silla aunque es un requisito aprobado. Es…","options":[{"id":"a","text":"Un cambio de alcance"},{"id":"b","text":"Una acción preventiva"},{"id":"c","text":"Una reparación de defecto"},{"id":"d","text":"Un riesgo"}]}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8280-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a08', 'quiz', 'Comprueba los conceptos', 'Tres preguntas sobre aceptación, transferencia y cierre de contratos.', '{"position":3,"hints_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000001","questions":[{"id":"q1","prompt":"¿Contra qué se aceptan formalmente los entregables?","options":[{"id":"a","text":"Contra la opinión del equipo"},{"id":"b","text":"Contra los criterios de aceptación del enunciado del alcance"},{"id":"c","text":"Contra el presupuesto gastado"},{"id":"d","text":"Contra lo que tenga la competencia"}],"answer":"b","explanation":"Los criterios de aceptación acordados en la planificación son la vara para aceptar."},{"id":"q2","prompt":"La agencia de diseño UX entregó todo y se le hizo el último pago. Esto es…","options":[{"id":"a","text":"Cierre del contrato"},{"id":"b","text":"Control de calidad"},{"id":"c","text":"Gestión de la configuración"},{"id":"d","text":"Acción correctiva"}],"answer":"a","explanation":"Verificar la entrega, pagar y liberar al proveedor es cerrar el contrato."},{"id":"q3","prompt":"¿Por qué se transfiere el producto al área de sistemas de la cooperativa?","options":[{"id":"a","text":"Para que el equipo del proyecto pueda liberarse y alguien opere el sistema"},{"id":"b","text":"Porque así lo exige el proveedor de pagos"},{"id":"c","text":"Para empezar un proyecto nuevo"},{"id":"d","text":"No es necesario transferirlo"}],"answer":"a","explanation":"El proyecto es temporal; la operación es permanente y la asume otra área."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8280-000000000002', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a08', 'simulacion', 'Ordena el cierre de RutaCaribe', 'Pon en orden los pasos para cerrar el proyecto.', '{"position":5,"kind":"secuencia","review_ai_activity_id":"c0a7e17d-0000-4000-8480-000000000003","instructions":"Usa las flechas para ordenar los pasos del cierre, del primero al último.","params":{"steps":[{"id":"s1","text":"Verificar que todos los entregables cumplen los criterios de aceptación","why":"No se puede pedir aceptación de algo que no se verificó."},{"id":"s2","text":"Obtener la aceptación formal firmada por la gerente","why":"La aceptación formal habilita el resto del cierre."},{"id":"s3","text":"Transferir el sistema, accesos y manuales al área de sistemas","why":"Se transfiere lo que ya fue aceptado."},{"id":"s4","text":"Cerrar los contratos con la agencia UX y el proveedor de hosting temporal","why":"Los contratos se cierran cuando su trabajo ya fue recibido y transferido."},{"id":"s5","text":"Hacer la sesión de lecciones aprendidas con el equipo","why":"Se hace antes de liberar al equipo, mientras todos siguen disponibles."},{"id":"s6","text":"Liberar al equipo y reconocer su trabajo","why":"Se libera al equipo cuando ya no se necesita para el cierre."},{"id":"s7","text":"Archivar la documentación y publicar el informe final","why":"El informe final resume todo lo anterior: es el último paso."}]}}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8280-000000000003', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a08', 'caso_estudio', 'El proyecto que no quería terminar', 'Dos meses después del lanzamiento, el proyecto sigue abierto. Ciérralo.', '{"position":7,"review_ai_activity_id":"c0a7e17d-0000-4000-8480-000000000001","variant_ai_activity_id":"c0a7e17d-0000-4000-8480-000000000002","scenario":"Febrero. RutaCaribe salió el 1 de diciembre y funciona, pero el proyecto **sigue abierto**:\n\n- La gerente nunca firmó la aceptación y cada semana pide \"un ajustico\" más.\n- Dos desarrolladores siguen asignados \"por si acaso\" y la cooperativa les paga.\n- El área de sistemas dice que no recibió los manuales y no sabe renovar el certificado SSL.\n- La agencia UX reclama su último pago.\n- Nadie documentó por qué la integración con PSE tomó el doble de lo estimado.\n\nLas ventas en línea ya son el 18 % del total.","questions":[{"id":"p1","prompt":"¿Qué pasos del cierre se omitieron y qué consecuencias está teniendo cada omisión?","placeholder":"Se omitió…"},{"id":"p2","prompt":"¿Cómo manejarías los \"ajusticos\" de la gerente para poder cerrar?","placeholder":"Con la gerente…"},{"id":"p3","prompt":"Escribe una lección aprendida sobre la integración con PSE con situación, impacto, causa y recomendación.","placeholder":"Situación… Impacto… Causa… Recomendación…"}],"rubric":[{"id":"c1","name":"Pasos del cierre","description":"Identifica aceptación, transferencia, cierre de contratos, lecciones y liberación del equipo como pendientes."},{"id":"c2","name":"Gestión del cliente","description":"Separa lo que es garantía o defecto de lo que es alcance nuevo, que va a otro proyecto o al control de cambios."},{"id":"c3","name":"Lección aprendida","description":"La lección tiene causa y una recomendación accionable para otros proyectos, no es una queja."},{"id":"c4","name":"Beneficios","description":"Relaciona el 18 % con el objetivo del 30 % del acta y propone cómo y cuándo medirlo."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8280-000000000004', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a08', 'colaborativa', 'Retrospectiva final del proyecto', 'El equipo hace su última retrospectiva. Aporta una lección desde tu rol.', '{"position":8,"role":"Director del proyecto","synthesis_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000004","prompt":"El equipo de RutaCaribe se reúne por última vez para acordar qué lecciones dejarán en el repositorio de la cooperativa para el próximo proyecto.","contributions":[{"author":"Juan David Barrios","role":"Líder técnico","text":"Lo mejor fue la capa aislada de pagos: cuando PSE cambió su API solo tocamos un módulo. Recomiendo hacerlo con cualquier proveedor externo."},{"author":"Andrés Castillo","role":"Analista de calidad","text":"Saltarnos las revisiones de código en la semana 9 nos costó tres semanas de corrección. La lección: la calidad no se negocia por fecha."},{"author":"Camila Herrera","role":"Diseñadora UX","text":"Los taquilleros fueron nuestros mejores probadores. Debimos invitarlos desde el inicio y no en la semana 12."}]}'::jsonb, '2026-09-01T13:00:00Z'),
  ('c0a7e17d-0000-4000-8280-000000000005', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a08', 'quiz', 'Autoevaluación: cierre', 'Cinco preguntas calificadas. Tu resultado queda en tu historial.', '{"position":100,"evaluation_id":"c0a7e17d-0000-4000-8380-000000000001","explain_ai_activity_id":"c0a7e17d-0000-4000-8400-000000000002","questions":[{"id":"e1","prompt":"¿Qué debe ocurrir antes de transferir el producto a operación?","options":[{"id":"a","text":"Liberar al equipo"},{"id":"b","text":"La aceptación formal de los entregables"},{"id":"c","text":"Archivar la documentación"},{"id":"d","text":"Iniciar el siguiente proyecto"}]},{"id":"e2","prompt":"¿Cuál es una lección aprendida bien escrita?","options":[{"id":"a","text":"PSE fue un desastre"},{"id":"b","text":"El equipo trabajó mucho"},{"id":"c","text":"La API de PSE no estaba documentada y la integración tardó el doble; en próximos proyectos, hacer una prueba técnica antes de estimar"},{"id":"d","text":"Todo salió bien"}]},{"id":"e3","prompt":"¿Por qué conviene hacer la sesión de lecciones aprendidas antes de liberar al equipo?","options":[{"id":"a","text":"Porque así lo exige el contrato"},{"id":"b","text":"Porque después las personas se dispersan y el conocimiento se pierde"},{"id":"c","text":"Porque se cobra aparte"},{"id":"d","text":"No importa el momento"}]},{"id":"e4","prompt":"Un beneficio como \"30 % de ventas en línea a los seis meses\" se mide…","options":[{"id":"a","text":"El día del lanzamiento"},{"id":"b","text":"Nunca: no es parte del proyecto"},{"id":"c","text":"Después del cierre, por quien el informe final designe"},{"id":"d","text":"Antes de firmar el acta"}]},{"id":"e5","prompt":"Verificar la entrega del proveedor, pagarle y liberarlo es…","options":[{"id":"a","text":"Cerrar el contrato"},{"id":"b","text":"Controlar el alcance"},{"id":"c","text":"Desarrollar el equipo"},{"id":"d","text":"Gestionar la configuración"}]}]}'::jsonb, '2026-09-01T13:00:00Z')
